<?php
require_once __DIR__ . '/auth.php';

$months=[]; $present=[]; $late=[]; $absent=[]; $leave=[]; $overtime=[];
for($i=5;$i>=0;$i--){ $ts=strtotime("first day of -$i month"); $months[]=date('M',$ts); $start=date('Y-m-01',$ts); $end=date('Y-m-t',$ts); $q=$conn->prepare("SELECT SUM(status='Present') p,SUM(status='Late') l,SUM(status='Absent') a,SUM(status='On Leave') o,COALESCE(SUM(ot_hours),0) ot FROM attendance WHERE attendance_date BETWEEN ? AND ?"); $q->bind_param('ss',$start,$end); $q->execute(); $r=$q->get_result()->fetch_assoc(); $present[]=(int)$r['p'];$late[]=(int)$r['l'];$absent[]=(int)$r['a'];$leave[]=(int)$r['o'];$overtime[]=(float)$r['ot']; }
$max=max(1,max($present),max($late),max($absent),max($leave));
$dept=[]; $q=$conn->query("SELECT department,COUNT(*) total FROM employees WHERE employment_status<>'Inactive' GROUP BY department ORDER BY total DESC LIMIT 6"); while($r=$q->fetch_assoc()) $dept[]=$r;
$leaveTypes=[]; $q=$conn->query("SELECT leave_type,COUNT(*) total FROM leave_requests GROUP BY leave_type ORDER BY total DESC"); while($r=$q->fetch_assoc()) $leaveTypes[]=$r;
$otTotal=array_sum($overtime);
$deptTotal=array_sum(array_column($dept,'total')); $offset=0; $segments=[]; $palette=['#4e9bff','#20c997','#ffc107','#ff6b6b','#9b7bff','#6c757d']; foreach($dept as $i=>$d){$pct=$deptTotal?($d['total']/$deptTotal)*100:0;$segments[]=$palette[$i%count($palette)].' '.round($offset,2).'% '.round($offset+$pct,2).'%';$offset+=$pct;}
$donut=$segments? 'conic-gradient('.implode(',',$segments).')':'#253149';
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Charts | Admin</title><link rel="stylesheet" href="../assets/css/bootstrap.min.css"><link rel="stylesheet" href="../assets/vendors/bootstrap-icons/bootstrap-icons.css"><link rel="stylesheet" href="../assets/css/style.css"><style>.analytics-bars{height:250px;display:flex;align-items:end;gap:14px}.bar-group{flex:1;display:flex;align-items:end;gap:4px;height:100%}.bar{flex:1;min-height:3px;border-radius:7px 7px 0 0}.bar.present{background:#4e9bff}.bar.late{background:#ffc107}.bar.absent{background:#ff6b6b}.bar.leave{background:#20c997}.donut{width:190px;height:190px;border-radius:50%;margin:10px auto 22px;position:relative;background:<?php echo $donut; ?>}.donut:after{content:'';position:absolute;inset:42px;background:#162237;border-radius:50%}.legend-dot{width:9px;height:9px;border-radius:50%;display:inline-block;margin-right:8px}</style></head>
