<main class="dashboard-content"><div class="container-fluid px-3 px-lg-4 py-4"><div class="page-heading"><div><p class="eyebrow mb-1">ANALYTICS</p><h1 class="h3 mb-1">Charts</h1><p class="text-muted mb-0">Workforce attendance, leave, overtime, and department analytics.</p></div></div>
<section class="row g-3"><div class="col-12 col-xl-8"><div class="panel h-100"><div class="panel-header"><div><h2 class="h5 mb-1 section-title"><i class="bi bi-bar-chart-line"></i><span>Attendance Overview</span></h2><p class="text-muted mb-0">Monthly attendance records for the last six months.</p></div></div><div class="p-4"><div class="d-flex gap-3 small mb-3 flex-wrap"><span><i class="legend-dot" style="background:#4e9bff"></i>Present</span><span><i class="legend-dot" style="background:#ffc107"></i>Late</span><span><i class="legend-dot" style="background:#ff6b6b"></i>Absent</span><span><i class="legend-dot" style="background:#20c997"></i>On Leave</span></div><div class="analytics-bars"><?php foreach($months as $i=>$m): ?><div class="bar-group" title="<?php echo e($m); ?>"><div class="bar present" style="height:<?php echo max(3,round($present[$i]/$max*100)); ?>%"></div><div class="bar late" style="height:<?php echo max(3,round($late[$i]/$max*100)); ?>%"></div><div class="bar absent" style="height:<?php echo max(3,round($absent[$i]/$max*100)); ?>%"></div><div class="bar leave" style="height:<?php echo max(3,round($leave[$i]/$max*100)); ?>%"></div></div><?php endforeach; ?></div><div class="d-flex justify-content-around text-muted small mt-2"><?php foreach($months as $m): ?><span><?php echo e($m); ?></span><?php endforeach; ?></div></div></div></div>
<div class="col-12 col-xl-4"><div class="panel h-100"><div class="panel-header"><div><h2 class="h5 mb-1 section-title"><i class="bi bi-pie-chart"></i><span>Workforce Distribution</span></h2><p class="text-muted mb-0">Active employees by department.</p></div></div><div class="p-4"><div class="donut"></div><?php if(!$dept): ?><p class="text-muted text-center">No employee data yet.</p><?php else: foreach($dept as $i=>$d): ?><div class="d-flex justify-content-between align-items-center border rounded p-2 mb-2"><span><i class="legend-dot" style="background:<?php echo $palette[$i%count($palette)]; ?>"></i><?php echo e($d['department']); ?></span><strong><?php echo (int)$d['total']; ?></strong></div><?php endforeach; endif; ?></div></div></div></section>
<section class="row g-3 mt-1"><div class="col-12 col-xl-7"><div class="panel"><div class="panel-header"><div><h2 class="h5 mb-1 section-title"><i class="bi bi-calendar2-check"></i><span>Leave Analysis</span></h2><p class="text-muted mb-0">Leave requests by type.</p></div></div><div class="p-4"><?php if(!$leaveTypes): ?><p class="text-muted mb-0">No leave requests yet.</p><?php else: foreach($leaveTypes as $l): ?><div class="d-flex align-items-center gap-3 mb-3"><div class="text-capitalize" style="width:120px"><?php echo e($l['leave_type']); ?></div><div class="progress flex-grow-1" style="height:10px"><div class="progress-bar" style="width:<?php echo min(100,($l['total']/max(1,max(array_column($leaveTypes,'total'))))*100); ?>%"></div></div><strong><?php echo (int)$l['total']; ?></strong></div><?php endforeach; endif; ?></div></div></div><div class="col-12 col-xl-5"><div class="panel h-100"><div class="panel-header"><div><h2 class="h5 mb-1 section-title"><i class="bi bi-stopwatch"></i><span>Overtime Analysis</span></h2><p class="text-muted mb-0">Total overtime hours by month.</p></div></div><div class="p-4"><div class="fs-2 fw-semibold"> <?php echo number_format($otTotal,2); ?> h</div><p class="text-muted small mb-3">Recorded overtime for the last six months.</p><?php foreach($months as $i=>$m): ?><div class="d-flex justify-content-between small mb-2"><span><?php echo e($m); ?></span><strong><?php echo number_format($overtime[$i],2); ?> h</strong></div><?php endforeach; ?></div></div></div></section>
